        <section class="rounded-2xl border p-4"><h2 class="mb-4 font-bold">Sửa đầu trang</h2><div class="grid gap-3 md:grid-cols-2"><label class="text-sm font-semibold">Dòng 1 trái (cấp trên)<input name="header_left_1" value="TỔNG CỤC HẬU CẦN" class="mt-1 block w-full rounded-lg border px-3 py-2.5"></label><label class="text-sm font-semibold">Dòng 2 trái (trường / đơn vị)<input name="header_left_2" value="TRƯỜNG CAO ĐẲNG HẬU CẦN 2" class="mt-1 block w-full rounded-lg border px-3 py-2.5"></label><label class="text-sm font-semibold">Số hiệu văn bản<input name="document_number" value="....../....../BC-CDHC" class="mt-1 block w-full rounded-lg border px-3 py-2.5"></label><label class="text-sm font-semibold">Địa danh (phần ghi ngày xuất)<input name="document_place" value="Thành phố Hồ Chí Minh" class="mt-1 block w-full rounded-lg border px-3 py-2.5"></label><label class="text-sm font-semibold md:col-span-2">Quốc hiệu<input name="national_title" value="CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM" class="mt-1 block w-full rounded-lg border px-3 py-2.5"></label><label class="text-sm font-semibold md:col-span-2">Tiêu ngữ<input name="national_motto" value="Độc lập - Tự do - Hạnh phúc" class="mt-1 block w-full rounded-lg border px-3 py-2.5"></label></div></section>
