<script>document.getElementById('template-default')?.addEventListener('click',()=>document.getElementById('word-template-form')?.reset());document.getElementById('word-template-form')?.addEventListener('submit',()=>{const f=document.getElementById('word-template-form');const data={};f.querySelectorAll('[name]').forEach(x=>{if(x.name!=='_token'&&x.name!=='code'&&x.name!=='name'&&x.name!=='description')data[x.name]=x.value});document.getElementById('template-description').value=JSON.stringify(data)});</script>
